backpatch(struct block *list, struct block *target)
{
        struct block *next;

        while (list) {
                if (!list->sense) {
                        next = JT(list);
                        JT(list) = target;
                } else {
                        next = JF(list);
                        JF(list) = target;
                }
                list = next;
        }
}

